// Parse GDACS RSS and keep only Orange/Red alerts within 300 km of Lahore.
const input = $input.first().json;
const raw = typeof input.data === 'string' ? input.data : JSON.stringify(input);

const FARM = { lat: 31.5204, lng: 74.3587, radiusKm: 300 };
const TYPE_LABEL = { EQ: 'earthquake', FL: 'flood', TC: 'cyclone', WF: 'wildfire', VO: 'volcano', DR: 'drought', TS: 'tsunami' };

const getTag = (block, name) => {
  const re = new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${name}>`, 'i');
  const m = block.match(re);
  return m ? m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim() : '';
};

const toRad = (d) => (d * Math.PI) / 180;
const distanceKm = (lat1, lng1, lat2, lng2) => {
  const R = 6371;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
};

const items = [...raw.matchAll(/<item>([\s\S]*?)<\/item>/gi)].map((m) => m[1]);
const staticData = $getWorkflowStaticData('global');
const seen = new Set(staticData.seenAlertIds || []);
const alerts = [];

for (const item of items) {
  const level = getTag(item, 'gdacs:alertlevel');
  if (!/orange|red/i.test(level)) continue;

  let lat = Number(getTag(item, 'geo:lat'));
  let lng = Number(getTag(item, 'geo:long'));
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    const point = getTag(item, 'georss:point').split(/\s+/).map(Number);
    [lat, lng] = point;
  }
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) continue;

  const dist = distanceKm(FARM.lat, FARM.lng, lat, lng);
  if (dist > FARM.radiusKm) continue;

  const id = `${getTag(item, 'gdacs:eventid')}-${getTag(item, 'gdacs:episodeid')}`;
  if (!id || id === '-' || seen.has(id)) continue;
  seen.add(id);

  alerts.push({
    json: {
      id,
      type: TYPE_LABEL[getTag(item, 'gdacs:eventtype')] || 'disaster',
      title: getTag(item, 'title') || 'Disaster alert',
      severity: level.toLowerCase(),
      country: getTag(item, 'gdacs:country'),
      lat, lng,
      distanceKm: Math.round(dist),
      source: 'GDACS',
      url: getTag(item, 'link') || 'https://www.gdacs.org',
      detectedAt: new Date().toISOString(),
    },
  });
}

staticData.seenAlertIds = [...seen].slice(-500);
return alerts;

// Demo alert enriched with the real Open-Meteo forecast for Lahore.
const w = $input.first().json || {};
const daily = w.daily || {};
const current = w.current || {};
const precip = Number(daily.precipitation_sum?.[0] ?? current.precipitation ?? 0);
const probability = Number(daily.precipitation_probability_max?.[0] ?? 0);
const code = Number(daily.weather_code?.[0] ?? current.weather_code ?? 0);
const gust = Number(daily.wind_gusts_10m_max?.[0] ?? current.wind_gusts_10m ?? 0);
const temp = current.temperature_2m != null ? Number(current.temperature_2m) : null;

const TYPES = [
  { type: 'flood', title: 'Flood warning near Lahore', severity: 'red' },
  { type: 'rain', title: 'Rain expected near Lahore', severity: 'orange' },
  { type: 'thunderstorm', title: 'Thunderstorm warning near Lahore', severity: 'red' },
  { type: 'wildfire', title: 'Wildfire near Lahore', severity: 'red' },
];
const t = TYPES[Math.floor(Math.random() * TYPES.length)];
let title = t.title;
if (t.type === 'rain' && precip > 0) title = `Rain expected near Lahore (${precip} mm)`;
if (t.type === 'thunderstorm' && code >= 95) title = `Thunderstorm warning near Lahore (code ${code})`;

return [{
  json: {
    id: 'TEST-' + Date.now().toString(36).toUpperCase(),
    type: t.type,
    title,
    severity: t.severity,
    country: 'Pakistan',
    lat: 31.5204,
    lng: 74.3587,
    distanceKm: 0,
    source: 'Test trigger + Open-Meteo',
    url: 'https://open-meteo.com/',
    detectedAt: new Date().toISOString(),
    test: true,
    details: { temperatureC: temp, precipitationMm: precip, probability, weatherCode: code, windGustKmh: gust },
  },
}];

// Turn the Open-Meteo daily forecast into an alert (real weather, no API key).
const d = $input.first().json;
const daily = d?.daily;
if (!daily || !Array.isArray(daily.time)) return [];

const i = 0;
const date = daily.time[i];
const precip = Number(daily.precipitation_sum?.[i] ?? 0);
const probability = Number(daily.precipitation_probability_max?.[i] ?? 0);
const code = Number(daily.weather_code?.[i] ?? 0);
const gust = Number(daily.wind_gusts_10m_max?.[i] ?? 0);

let type = null;
let severity = null;
let title = null;

if (code >= 95) {
  type = 'thunderstorm';
  severity = 'red';
  title = 'Thunderstorm warning near Lahore';
} else if (code >= 51 || precip >= 0.5) {
  type = 'rain';
  severity = 'orange';
  title = precip >= 5
    ? `Heavy rain warning near Lahore (${precip} mm)`
    : `Rain expected near Lahore (${precip} mm)`;
} else if (gust >= 60) {
  type = 'wind';
  severity = 'orange';
  title = `High wind warning near Lahore (${gust} km/h)`;
}

if (!type) return [];

const staticData = $getWorkflowStaticData('global');
const seen = new Set(staticData.seenWeatherKeys || []);
const key = `weather-${date}-${type}`;
if (seen.has(key)) return [];
seen.add(key);
staticData.seenWeatherKeys = [...seen].slice(-30);

return [{
  json: {
    id: key,
    type,
    title,
    severity,
    country: 'Pakistan',
    lat: 31.5204,
    lng: 74.3587,
    distanceKm: 0,
    source: 'Open-Meteo',
    url: 'https://open-meteo.com/',
    detectedAt: new Date().toISOString(),
    details: { precipitationMm: precip, probability, weatherCode: code, windGustKmh: gust, date },
  },
}];
